"""Command line interface: ``dq validate``, ``dq lineage``,
``dq field-lineage``, ``dq lineage-paths``, ``dq field-lineage-paths``,
``dq correlate``, ``dq correlate-links``, ``dq query-results``.

All subcommands read a UTF-8 JSON object from standard input and write a
UTF-8 JSON result to standard output.

``dq validate`` reads ``{"records": [...], "rules": [...], "dataset": ...,
"composite_rules": [...], "record_refs": [...]}`` where ``dataset`` is
required when ``composite_rules`` is present and ``composite_rules`` /
``record_refs`` are optional.
``dq query-results`` reads ``{"results": [...], "rule_id": ...,
"severity": ..., "record_index": ..., "record_id": ...}`` where every
filter is optional.
``dq lineage`` reads ``{"nodes": [...], "edges": [...], "target": ...,
"direction": ..., "max_depth": ...}`` where ``direction`` and ``max_depth``
are optional.
``dq field-lineage`` reads ``{"fields": {...}, "edges": [...], "target": ...,
"direction": ..., "max_depth": ...}`` where ``direction`` and ``max_depth``
are optional.
``dq lineage-paths`` reads the same payload as ``dq lineage`` and explains
the concrete upstream/downstream paths of the target.
``dq field-lineage-paths`` reads the same payload as ``dq field-lineage``
and explains the concrete field-level upstream/downstream paths.
``dq correlate`` reads ``{"results": [...], "lineage": {...}}``.
``dq correlate-links`` reads ``{"results": [...], "lineage": {...},
"sample_links": [...]}``.

Error JSON has the shape ``{"error": {"code": ..., "message": ...}}`` and
the process exits with status 2:

* ``INVALID_JSON``                    - stdin is not parseable UTF-8 JSON
* ``INVALID_INPUT``                   - validate payload/records is malformed
* ``INVALID_RULE``                    - a validate rule is malformed/conflicting
* ``INVALID_RULE_SET``                - composite rule set is empty/unusable
* ``DUPLICATE_RULE_ID``               - two composite rules share a rule_id
* ``INVALID_SEVERITY``                - composite rule severity is unknown
* ``UNSUPPORTED_COMPOSITE_CONDITION`` - composite condition type unsupported
* ``INVALID_COMPOSITE_RULE``          - composite rule cannot be executed
                                        (unknown/self-referencing field, bad
                                        date field, malformed condition)
* ``INVALID_RECORD_REFERENCE``        - record locator cannot be resolved
* ``INVALID_LINEAGE_INPUT``           - lineage nodes/edges are missing/malformed
* ``INVALID_LINEAGE_QUERY``           - lineage target/direction/max_depth is bad
* ``UNKNOWN_LINEAGE_TARGET``          - lineage target is not declared in nodes
* ``INVALID_FIELD_LINEAGE_INPUT``     - field-lineage fields/edges are malformed
* ``INVALID_FIELD_LINEAGE_QUERY``     - field-lineage target/direction/max_depth
                                        is invalid
* ``UNKNOWN_FIELD_LINEAGE_TARGET``    - field-lineage target is not declared
* ``LINEAGE_NODE_NOT_FOUND``          - lineage-paths target is not declared
* ``INVALID_CORRELATION_INPUT``       - correlate results/lineage are malformed
* ``UNKNOWN_CORRELATION_REFERENCE``   - correlate result references an
                                        undeclared dataset or field
* ``INVALID_LINKED_CORRELATION_INPUT`` - correlate-links sample_links are
                                         malformed
* ``UNKNOWN_LINKED_CORRELATION_REFERENCE`` - correlate-links sample link
                                            endpoint has no matching result
"""

from __future__ import annotations

import argparse
import json
import sys
from typing import Any, List, Optional

from .composite import query_composite_results
from .correlation import (
    InvalidCorrelationInputError,
    InvalidLinkedCorrelationInputError,
    UnknownCorrelationReferenceError,
    UnknownLinkedCorrelationReferenceError,
    correlate_linked_violations,
    correlate_violations,
)
from .field_lineage import (
    InvalidFieldLineageInputError,
    InvalidFieldLineageQueryError,
    UnknownFieldLineageTargetError,
    trace_field_lineage,
)
from .lineage import (
    InvalidLineageInputError,
    InvalidLineageQueryError,
    UnknownLineageTargetError,
    trace_lineage,
)
from .lineage_paths import (
    LineageNodeNotFoundError,
    explain_field_lineage_paths,
    explain_lineage_paths,
)
from .validator import (
    DataQualityError,
    InvalidInputError,
    InvalidRuleError,
    validate,
)

EXIT_OK = 0
EXIT_ERROR = 2

# Sentinel distinguishing "error already emitted" from a parsed payload.
_PARSE_FAILED = object()


def _emit_error(code: str, message: str) -> int:
    payload = {"error": {"code": code, "message": message}}
    json.dump(payload, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return EXIT_ERROR


def _read_json_payload() -> Any:
    """Read stdin as a UTF-8 JSON value.

    Returns the parsed value, or ``_PARSE_FAILED`` after emitting an
    ``INVALID_JSON`` error.
    """
    raw = sys.stdin.buffer.read()

    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        _emit_error("INVALID_JSON", f"input is not valid UTF-8: {exc}")
        return _PARSE_FAILED

    try:
        return json.loads(text)
    except json.JSONDecodeError as exc:
        _emit_error("INVALID_JSON", f"input is not valid JSON: {exc.msg}")
        return _PARSE_FAILED


def _run_validate() -> int:
    payload = _read_json_payload()
    if payload is _PARSE_FAILED:
        return EXIT_ERROR

    if not isinstance(payload, dict):
        return _emit_error(
            "INVALID_INPUT", "input payload must be a JSON object"
        )
    if "records" not in payload:
        return _emit_error("INVALID_INPUT", "payload is missing 'records'")
    if "rules" not in payload:
        return _emit_error("INVALID_INPUT", "payload is missing 'rules'")

    try:
        result = validate(
            payload["records"],
            payload["rules"],
            dataset=payload.get("dataset"),
            composite_rules=payload.get("composite_rules"),
            record_refs=payload.get("record_refs"),
        )
    except InvalidRuleError as exc:
        return _emit_error("INVALID_RULE", str(exc))
    except InvalidInputError as exc:
        return _emit_error("INVALID_INPUT", str(exc))
    except DataQualityError as exc:
        return _emit_error(exc.code, str(exc))

    json.dump(result, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return EXIT_OK


def _run_query_results() -> int:
    payload = _read_json_payload()
    if payload is _PARSE_FAILED:
        return EXIT_ERROR

    if not isinstance(payload, dict):
        return _emit_error(
            "INVALID_INPUT", "input payload must be a JSON object"
        )
    if "results" not in payload:
        return _emit_error("INVALID_INPUT", "payload is missing 'results'")

    try:
        result = query_composite_results(
            payload["results"],
            rule_id=payload.get("rule_id"),
            severity=payload.get("severity"),
            record_index=payload.get("record_index"),
            record_id=payload.get("record_id"),
        )
    except DataQualityError as exc:
        return _emit_error(exc.code, str(exc))
    except ValueError as exc:
        return _emit_error("INVALID_INPUT", str(exc))

    json.dump(result, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return EXIT_OK


def _run_lineage() -> int:
    payload = _read_json_payload()
    if payload is _PARSE_FAILED:
        return EXIT_ERROR

    if not isinstance(payload, dict):
        return _emit_error(
            "INVALID_LINEAGE_INPUT", "input payload must be a JSON object"
        )

    try:
        result = trace_lineage(
            payload.get("nodes"),
            payload.get("edges"),
            payload.get("target"),
            payload.get("direction", "both"),
            payload.get("max_depth", None),
        )
    except InvalidLineageInputError as exc:
        return _emit_error("INVALID_LINEAGE_INPUT", str(exc))
    except InvalidLineageQueryError as exc:
        return _emit_error("INVALID_LINEAGE_QUERY", str(exc))
    except UnknownLineageTargetError as exc:
        return _emit_error("UNKNOWN_LINEAGE_TARGET", str(exc))

    json.dump(result, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return EXIT_OK


def _run_field_lineage() -> int:
    payload = _read_json_payload()
    if payload is _PARSE_FAILED:
        return EXIT_ERROR

    if not isinstance(payload, dict):
        return _emit_error(
            "INVALID_FIELD_LINEAGE_INPUT", "input payload must be a JSON object"
        )

    try:
        result = trace_field_lineage(
            payload.get("fields"),
            payload.get("edges"),
            payload.get("target"),
            payload.get("direction", "both"),
            payload.get("max_depth", None),
        )
    except InvalidFieldLineageInputError as exc:
        return _emit_error("INVALID_FIELD_LINEAGE_INPUT", str(exc))
    except InvalidFieldLineageQueryError as exc:
        return _emit_error("INVALID_FIELD_LINEAGE_QUERY", str(exc))
    except UnknownFieldLineageTargetError as exc:
        return _emit_error("UNKNOWN_FIELD_LINEAGE_TARGET", str(exc))

    json.dump(result, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return EXIT_OK


def _run_lineage_paths() -> int:
    payload = _read_json_payload()
    if payload is _PARSE_FAILED:
        return EXIT_ERROR

    if not isinstance(payload, dict):
        return _emit_error(
            "INVALID_LINEAGE_INPUT", "input payload must be a JSON object"
        )

    try:
        result = explain_lineage_paths(
            payload.get("nodes"),
            payload.get("edges"),
            payload.get("target"),
            payload.get("direction", "both"),
            payload.get("max_depth", None),
        )
    except InvalidLineageInputError as exc:
        return _emit_error("INVALID_LINEAGE_INPUT", str(exc))
    except InvalidLineageQueryError as exc:
        return _emit_error("INVALID_LINEAGE_QUERY", str(exc))
    except LineageNodeNotFoundError as exc:
        return _emit_error(exc.code, str(exc))

    json.dump(result, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return EXIT_OK


def _run_field_lineage_paths() -> int:
    payload = _read_json_payload()
    if payload is _PARSE_FAILED:
        return EXIT_ERROR

    if not isinstance(payload, dict):
        return _emit_error(
            "INVALID_FIELD_LINEAGE_INPUT", "input payload must be a JSON object"
        )

    try:
        result = explain_field_lineage_paths(
            payload.get("fields"),
            payload.get("edges"),
            payload.get("target"),
            payload.get("direction", "both"),
            payload.get("max_depth", None),
        )
    except InvalidFieldLineageInputError as exc:
        return _emit_error("INVALID_FIELD_LINEAGE_INPUT", str(exc))
    except InvalidFieldLineageQueryError as exc:
        return _emit_error("INVALID_FIELD_LINEAGE_QUERY", str(exc))
    except LineageNodeNotFoundError as exc:
        return _emit_error(exc.code, str(exc))

    json.dump(result, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return EXIT_OK


def _run_correlate() -> int:
    payload = _read_json_payload()
    if payload is _PARSE_FAILED:
        return EXIT_ERROR

    if not isinstance(payload, dict):
        return _emit_error(
            "INVALID_CORRELATION_INPUT", "input payload must be a JSON object"
        )

    try:
        result = correlate_violations(
            payload.get("results"),
            payload.get("lineage"),
        )
    except InvalidCorrelationInputError as exc:
        return _emit_error("INVALID_CORRELATION_INPUT", str(exc))
    except UnknownCorrelationReferenceError as exc:
        return _emit_error("UNKNOWN_CORRELATION_REFERENCE", str(exc))

    json.dump(result, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return EXIT_OK


def _run_correlate_links() -> int:
    payload = _read_json_payload()
    if payload is _PARSE_FAILED:
        return EXIT_ERROR

    if not isinstance(payload, dict):
        return _emit_error(
            "INVALID_LINKED_CORRELATION_INPUT",
            "input payload must be a JSON object",
        )

    try:
        result = correlate_linked_violations(
            payload.get("results"),
            payload.get("lineage"),
            payload.get("sample_links"),
        )
    except InvalidCorrelationInputError as exc:
        return _emit_error("INVALID_CORRELATION_INPUT", str(exc))
    except UnknownCorrelationReferenceError as exc:
        return _emit_error("UNKNOWN_CORRELATION_REFERENCE", str(exc))
    except InvalidLinkedCorrelationInputError as exc:
        return _emit_error("INVALID_LINKED_CORRELATION_INPUT", str(exc))
    except UnknownLinkedCorrelationReferenceError as exc:
        return _emit_error("UNKNOWN_LINKED_CORRELATION_REFERENCE", str(exc))

    json.dump(result, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return EXIT_OK


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="dq",
        description="Data quality rule validation and lineage tracing.",
    )
    subparsers = parser.add_subparsers(dest="command", required=True)

    validate_parser = subparsers.add_parser(
        "validate",
        help="validate records from a UTF-8 JSON object on standard input",
    )
    validate_parser.set_defaults(handler=_run_validate)

    lineage_parser = subparsers.add_parser(
        "lineage",
        help="trace upstream/downstream lineage from a UTF-8 JSON object "
        "on standard input",
    )
    lineage_parser.set_defaults(handler=_run_lineage)

    field_lineage_parser = subparsers.add_parser(
        "field-lineage",
        help="trace upstream/downstream field-level lineage from a UTF-8 "
        "JSON object on standard input",
    )
    field_lineage_parser.set_defaults(handler=_run_field_lineage)

    lineage_paths_parser = subparsers.add_parser(
        "lineage-paths",
        help="explain ordered upstream/downstream lineage paths from a "
        "UTF-8 JSON object on standard input",
    )
    lineage_paths_parser.set_defaults(handler=_run_lineage_paths)

    field_lineage_paths_parser = subparsers.add_parser(
        "field-lineage-paths",
        help="explain ordered upstream/downstream field-level lineage paths "
        "from a UTF-8 JSON object on standard input",
    )
    field_lineage_paths_parser.set_defaults(handler=_run_field_lineage_paths)

    correlate_parser = subparsers.add_parser(
        "correlate",
        help="group violation results into cross-rule correlation events "
        "from a UTF-8 JSON object on standard input",
    )
    correlate_parser.set_defaults(handler=_run_correlate)

    correlate_links_parser = subparsers.add_parser(
        "correlate-links",
        help="group violation results across linked samples into "
        "cross-dataset correlation events from a UTF-8 JSON object on "
        "standard input",
    )
    correlate_links_parser.set_defaults(handler=_run_correlate_links)

    query_results_parser = subparsers.add_parser(
        "query-results",
        help="filter complete composite rule results by rule id, severity "
        "or record locator from a UTF-8 JSON object on standard input",
    )
    query_results_parser.set_defaults(handler=_run_query_results)
    return parser


def main(argv: Optional[List[str]] = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    return args.handler()


if __name__ == "__main__":
    sys.exit(main())

"""Cross-rule correlation of anomalous samples over a field lineage graph.

The public entry points are :func:`correlate_violations` and
:func:`correlate_linked_violations`. They take a batch of data quality check
results (each carrying a stable sample id) plus a lineage graph of
dataset/field nodes joined by typed upstream/downstream edges.

``correlate_violations`` groups the violation results that share a sample and
were triggered by the same field or by lineage-adjacent fields into one
correlation event per connected group.

``correlate_linked_violations`` additionally takes an undirected
``sample_links`` graph that relates samples, potentially across datasets. It
builds sample references from each result's ``dataset_id`` and
``sample_id``, takes the undirected transitive closure of the links so each
connected component of samples becomes one association group, and emits one
correlation event per lineage-connected cluster of violated fields inside
that group.

Malformed check results, lineage graphs or sample links raise
:class:`InvalidCorrelationInputError` /
:class:`InvalidLinkedCorrelationInputError` (both :class:`ValueError`); check
results referencing datasets or fields not declared in the lineage graph
raise :class:`UnknownCorrelationReferenceError`, and sample-link endpoints
that do not match a result raise
:class:`UnknownLinkedCorrelationReferenceError` (both :class:`LookupError`).
"""

from __future__ import annotations

from typing import Any, Dict, FrozenSet, List, Set, Tuple

__all__ = [
    "correlate_violations",
    "correlate_linked_violations",
    "InvalidCorrelationInputError",
    "UnknownCorrelationReferenceError",
    "InvalidLinkedCorrelationInputError",
    "UnknownLinkedCorrelationReferenceError",
]

EDGE_TYPES = ("upstream", "downstream")

_RESULT_KEYS = frozenset(
    {"rule_id", "dataset_id", "field_id", "sample_id", "violated", "value"}
)
_LINEAGE_KEYS = frozenset({"datasets", "fields", "edges"})
_EDGE_KEYS = frozenset({"source", "target", "type"})
_ENDPOINT_KEYS = frozenset({"dataset", "field"})
_LINK_KEYS = frozenset({"left", "right"})
_LINK_ENDPOINT_KEYS = frozenset({"dataset_id", "sample_id"})

# A field is identified by its (dataset, field) pair.
FieldId = Tuple[str, str]

# A sample reference is identified by its (dataset, sample) pair.
SampleRef = Tuple[str, str]


class InvalidCorrelationInputError(ValueError):
    """The check results or the lineage graph are malformed."""

    code = "INVALID_CORRELATION_INPUT"


class UnknownCorrelationReferenceError(LookupError):
    """A check result references an undeclared dataset or field."""

    code = "UNKNOWN_CORRELATION_REFERENCE"


class InvalidLinkedCorrelationInputError(ValueError):
    """The sample links are malformed."""

    code = "INVALID_LINKED_CORRELATION_INPUT"


class UnknownLinkedCorrelationReferenceError(LookupError):
    """A sample-link endpoint does not match any check result."""

    code = "UNKNOWN_LINKED_CORRELATION_REFERENCE"


def _input_error(message: str) -> InvalidCorrelationInputError:
    return InvalidCorrelationInputError(message)


def _linked_input_error(
    message: str,
) -> InvalidLinkedCorrelationInputError:
    return InvalidLinkedCorrelationInputError(message)


def _json_equal(left: Any, right: Any) -> bool:
    """JSON value equality.

    Unlike Python ``==`` this never considers booleans equal to numbers
    (JSON ``true`` is not ``1``) and compares containers structurally.
    """
    if isinstance(left, bool) or isinstance(right, bool):
        return isinstance(left, bool) and isinstance(right, bool) and left == right
    if isinstance(left, list) and isinstance(right, list):
        return len(left) == len(right) and all(
            _json_equal(a, b) for a, b in zip(left, right)
        )
    if isinstance(left, dict) and isinstance(right, dict):
        return left.keys() == right.keys() and all(
            _json_equal(left[k], right[k]) for k in left
        )
    return left == right


def _check_keys(obj: Dict[str, Any], expected: frozenset, where: str) -> None:
    keys = set(obj)
    if keys != expected:
        missing = sorted(expected - keys)
        if missing:
            raise _input_error(f"{where} is missing keys: {missing}")
        unknown = sorted(keys - expected)
        raise _input_error(f"{where} has unsupported keys: {unknown}")


def _validate_endpoint(
    endpoint: Any, declared_fields: Set[FieldId], where: str
) -> FieldId:
    if not isinstance(endpoint, dict):
        raise _input_error(f"{where} must be an object")
    _check_keys(endpoint, _ENDPOINT_KEYS, where)
    dataset = endpoint["dataset"]
    field = endpoint["field"]
    if not isinstance(dataset, str) or not dataset:
        raise _input_error(f"{where}.dataset must be a non-empty string")
    if not isinstance(field, str) or not field:
        raise _input_error(f"{where}.field must be a non-empty string")
    if (dataset, field) not in declared_fields:
        raise _input_error(f"{where} is not a declared field: {endpoint!r}")
    return (dataset, field)


def _validate_lineage(
    lineage: Any,
) -> Tuple[Set[str], Set[FieldId], Set[Tuple[FieldId, FieldId]]]:
    """Validate the lineage graph.

    Returns the declared dataset ids, the declared ``(dataset, field)``
    field ids and the canonical edges as ``(upstream_field,
    downstream_field)`` pairs.
    """
    if not isinstance(lineage, dict):
        raise _input_error("lineage must be an object")
    _check_keys(lineage, _LINEAGE_KEYS, "lineage")

    datasets = lineage["datasets"]
    if not isinstance(datasets, list):
        raise _input_error("lineage.datasets must be a list of dataset ids")
    declared_datasets: Set[str] = set()
    for index, dataset in enumerate(datasets):
        if not isinstance(dataset, str) or not dataset:
            raise _input_error(
                f"lineage.datasets[{index}] must be a non-empty string"
            )
        if dataset in declared_datasets:
            raise _input_error(f"duplicate dataset id: {dataset!r}")
        declared_datasets.add(dataset)

    fields = lineage["fields"]
    if not isinstance(fields, dict):
        raise _input_error(
            "lineage.fields must be an object mapping dataset ids to "
            "field id lists"
        )
    declared_fields: Set[FieldId] = set()
    for dataset, columns in fields.items():
        if not isinstance(dataset, str) or not dataset:
            raise _input_error(
                f"lineage.fields key must be a non-empty dataset id "
                f"string: {dataset!r}"
            )
        if dataset not in declared_datasets:
            raise _input_error(
                f"lineage.fields declares fields for an undeclared "
                f"dataset: {dataset!r}"
            )
        if not isinstance(columns, list):
            raise _input_error(
                f"lineage.fields[{dataset!r}] must be a list of field ids"
            )
        seen_columns: Set[str] = set()
        for index, column in enumerate(columns):
            if not isinstance(column, str) or not column:
                raise _input_error(
                    f"lineage.fields[{dataset!r}][{index}] must be a "
                    "non-empty field id string"
                )
            if column in seen_columns:
                raise _input_error(
                    f"duplicate field id in dataset {dataset!r}: {column!r}"
                )
            seen_columns.add(column)
            declared_fields.add((dataset, column))

    edges = lineage["edges"]
    if not isinstance(edges, list):
        raise _input_error("lineage.edges must be a list")
    canonical: Set[Tuple[FieldId, FieldId]] = set()
    for index, edge in enumerate(edges):
        if not isinstance(edge, dict):
            raise _input_error(f"lineage.edges[{index}] must be an object")
        _check_keys(edge, _EDGE_KEYS, f"lineage.edges[{index}]")

        edge_type = edge["type"]
        if edge_type not in EDGE_TYPES:
            raise _input_error(
                f"lineage.edges[{index}].type must be one of "
                f"{list(EDGE_TYPES)}, got {edge_type!r}"
            )

        source = _validate_endpoint(
            edge["source"], declared_fields, f"lineage.edges[{index}].source"
        )
        target = _validate_endpoint(
            edge["target"], declared_fields, f"lineage.edges[{index}].target"
        )

        # Canonical form is (upstream field, downstream field): an
        # "upstream" edge declares its target upstream of its source, a
        # "downstream" edge declares its target downstream of its source.
        if edge_type == "upstream":
            pair = (target, source)
        else:
            pair = (source, target)
        if pair in canonical:
            # Identical restatement of an already known edge: keep one.
            continue
        if (pair[1], pair[0]) in canonical:
            raise _input_error(
                f"contradictory edges between {pair[1]!r} and {pair[0]!r}"
            )
        canonical.add(pair)

    return declared_datasets, declared_fields, canonical


def _same_content(left: Dict[str, Any], right: Dict[str, Any]) -> bool:
    return (
        left["dataset_id"] == right["dataset_id"]
        and left["field_id"] == right["field_id"]
        and left["violated"] == right["violated"]
        and _json_equal(left["value"], right["value"])
    )


def _validate_results(results: Any) -> List[Dict[str, Any]]:
    if not isinstance(results, list):
        raise _input_error("results must be a list")

    deduped: List[Dict[str, Any]] = []
    by_rule_sample: Dict[Tuple[str, str], Dict[str, Any]] = {}
    for index, result in enumerate(results):
        if not isinstance(result, dict):
            raise _input_error(f"results[{index}] must be an object")
        _check_keys(result, _RESULT_KEYS, f"results[{index}]")

        for key in ("rule_id", "dataset_id", "field_id", "sample_id"):
            if not isinstance(result[key], str) or not result[key]:
                raise _input_error(
                    f"results[{index}].{key} must be a non-empty string"
                )
        if not isinstance(result["violated"], bool):
            raise _input_error(f"results[{index}].violated must be a boolean")

        dedup_key = (result["rule_id"], result["sample_id"])
        existing = by_rule_sample.get(dedup_key)
        if existing is None:
            by_rule_sample[dedup_key] = result
            deduped.append(result)
        elif not _same_content(existing, result):
            raise _input_error(
                f"conflicting results for rule {result['rule_id']!r} on "
                f"sample {result['sample_id']!r}"
            )
    return deduped


def _check_references(
    results: List[Dict[str, Any]],
    declared_datasets: Set[str],
    declared_fields: Set[FieldId],
) -> None:
    for result in results:
        dataset = result["dataset_id"]
        if dataset not in declared_datasets:
            raise UnknownCorrelationReferenceError(
                f"unknown dataset id: {dataset!r}"
            )
        if (dataset, result["field_id"]) not in declared_fields:
            raise UnknownCorrelationReferenceError(
                f"unknown field: {dataset!r}.{result['field_id']}"
            )


def _field_ref(field: FieldId) -> Dict[str, str]:
    return {"dataset": field[0], "field": field[1]}


def _sample_ref(ref: SampleRef) -> Dict[str, str]:
    return {"dataset_id": ref[0], "sample_id": ref[1]}


def _direct_lineage_neighbours(
    edges: Set[Tuple[FieldId, FieldId]],
) -> Tuple[Dict[FieldId, Set[FieldId]], Dict[FieldId, Set[FieldId]]]:
    """Build the direct upstream/downstream adjacency of canonical edges."""
    upstream_of: Dict[FieldId, Set[FieldId]] = {}
    downstream_of: Dict[FieldId, Set[FieldId]] = {}
    for upstream, downstream in edges:
        downstream_of.setdefault(upstream, set()).add(downstream)
        upstream_of.setdefault(downstream, set()).add(upstream)
    return upstream_of, downstream_of


def _lineage_field_components(
    violated_fields: Set[FieldId], edges: Set[Tuple[FieldId, FieldId]]
) -> List[Set[FieldId]]:
    """Connected components of violated fields joined by lineage edges.

    Two violated fields are adjacent when a single valid lineage edge
    connects them (in either direction). Fields that merely share a
    dataset without an edge stay in separate components. Traversal order
    is deterministic so equal inputs always compare equal.
    """
    neighbours: Dict[FieldId, Set[FieldId]] = {
        field: set() for field in violated_fields
    }
    for upstream, downstream in edges:
        if upstream in violated_fields and downstream in violated_fields:
            neighbours[upstream].add(downstream)
            neighbours[downstream].add(upstream)

    components: List[Set[FieldId]] = []
    seen: Set[FieldId] = set()
    for seed in sorted(violated_fields):
        if seed in seen:
            continue
        component: Set[FieldId] = set()
        stack = [seed]
        seen.add(seed)
        while stack:
            current = stack.pop()
            component.add(current)
            for nxt in sorted(neighbours[current]):
                if nxt not in seen:
                    seen.add(nxt)
                    stack.append(nxt)
        components.append(component)
    return components


def _validate_link_endpoint(endpoint: Any, where: str) -> SampleRef:
    if not isinstance(endpoint, dict):
        raise _linked_input_error(f"{where} must be an object")
    keys = set(endpoint)
    if keys != _LINK_ENDPOINT_KEYS:
        missing = sorted(_LINK_ENDPOINT_KEYS - keys)
        if missing:
            raise _linked_input_error(f"{where} is missing keys: {missing}")
        unknown = sorted(keys - _LINK_ENDPOINT_KEYS)
        raise _linked_input_error(f"{where} has unsupported keys: {unknown}")
    dataset = endpoint["dataset_id"]
    sample = endpoint["sample_id"]
    if not isinstance(dataset, str) or not dataset:
        raise _linked_input_error(
            f"{where}.dataset_id must be a non-empty string"
        )
    if not isinstance(sample, str) or not sample:
        raise _linked_input_error(
            f"{where}.sample_id must be a non-empty string"
        )
    return (dataset, sample)


def _validate_sample_links(
    sample_links: Any, records: List[Dict[str, Any]]
) -> List[Tuple[SampleRef, SampleRef]]:
    """Validate the undirected sample link graph.

    Returns the links as ``(left_ref, right_ref)`` pairs. Structural
    problems (not a list, missing/extra keys, empty identifiers), self
    links and duplicate (including reversed) relationships raise
    :class:`InvalidLinkedCorrelationInputError`; endpoints that do not
    match any result raise
    :class:`UnknownLinkedCorrelationReferenceError`. Structural problems
    are reported before unknown references.
    """
    if not isinstance(sample_links, list):
        raise _linked_input_error("sample_links must be a list")

    pairs: List[Tuple[SampleRef, SampleRef]] = []
    for index, link in enumerate(sample_links):
        if not isinstance(link, dict):
            raise _linked_input_error(
                f"sample_links[{index}] must be an object"
            )
        keys = set(link)
        if keys != _LINK_KEYS:
            missing = sorted(_LINK_KEYS - keys)
            if missing:
                raise _linked_input_error(
                    f"sample_links[{index}] is missing keys: {missing}"
                )
            unknown = sorted(keys - _LINK_KEYS)
            raise _linked_input_error(
                f"sample_links[{index}] has unsupported keys: {unknown}"
            )
        left = _validate_link_endpoint(
            link["left"], f"sample_links[{index}].left"
        )
        right = _validate_link_endpoint(
            link["right"], f"sample_links[{index}].right"
        )
        pairs.append((left, right))

    # Self links and duplicate relationships are structural errors and
    # take precedence over unknown-reference errors.
    seen_relations: Set[FrozenSet[SampleRef]] = set()
    for left, right in pairs:
        if left == right:
            raise _linked_input_error(
                f"sample link connects a sample to itself: "
                f"{_sample_ref(left)!r}"
            )
        relation = frozenset((left, right))
        if relation in seen_relations:
            raise _linked_input_error(
                f"duplicate sample link between {_sample_ref(left)!r} and "
                f"{_sample_ref(right)!r}"
            )
        seen_relations.add(relation)

    known_refs: Set[SampleRef] = {
        (record["dataset_id"], record["sample_id"]) for record in records
    }
    for left, right in pairs:
        for endpoint in (left, right):
            if endpoint not in known_refs:
                raise UnknownLinkedCorrelationReferenceError(
                    f"sample link endpoint has no matching result: "
                    f"{_sample_ref(endpoint)!r}"
                )

    return pairs


def _sample_components(
    records: List[Dict[str, Any]],
    links: List[Tuple[SampleRef, SampleRef]],
) -> List[Set[SampleRef]]:
    """Undirected connected components over every result sample ref."""
    refs: Set[SampleRef] = {
        (record["dataset_id"], record["sample_id"]) for record in records
    }
    neighbours: Dict[SampleRef, Set[SampleRef]] = {ref: set() for ref in refs}
    for left, right in links:
        neighbours[left].add(right)
        neighbours[right].add(left)

    components: List[Set[SampleRef]] = []
    seen: Set[SampleRef] = set()
    for seed in sorted(refs):
        if seed in seen:
            continue
        component: Set[SampleRef] = set()
        stack = [seed]
        seen.add(seed)
        while stack:
            current = stack.pop()
            component.add(current)
            for nxt in sorted(neighbours[current]):
                if nxt not in seen:
                    seen.add(nxt)
                    stack.append(nxt)
        components.append(component)
    return components


def correlate_violations(results: Any, lineage: Any) -> Dict[str, Any]:
    """Group violation results on the same sample into correlation events.

    :param results: list of check result objects, each with exactly the
        keys ``rule_id``, ``dataset_id``, ``field_id``, ``sample_id``
        (non-empty strings), ``violated`` (boolean) and ``value`` (any
        JSON value). The same rule appearing more than once for the same
        sample is kept once; conflicting repetitions are rejected.
    :param lineage: object with exactly the keys ``datasets`` (list of
        distinct non-empty dataset ids), ``fields`` (object mapping
        declared dataset ids to lists of distinct non-empty field ids)
        and ``edges`` (list of ``{"source": ..., "target": ...,
        "type": ...}`` objects whose endpoints are ``{"dataset": ...,
        "field": ...}`` objects declared in ``fields`` and whose type is
        ``"upstream"`` or ``"downstream"``). Identical restatements of an
        edge are kept once; mutually contradictory edges are rejected.
    :returns: ``{"events": [...]}`` where each event is ``{"sample_id",
        "rules", "fields", "upstream_fields", "downstream_fields"}``.
        ``rules`` are the violated rule ids sorted ascending; ``fields``
        are the affected ``{"dataset", "field"}`` objects; the upstream
        and downstream sets hold the direct lineage neighbours of the
        affected fields outside the event itself. All field collections
        are deduplicated and sorted by ``(dataset, field)``; events are
        sorted by sample id. Samples without violations produce no
        events, so an all-passing batch yields ``{"events": []}``.
    :raises ValueError: :class:`InvalidCorrelationInputError` on malformed
        results or lineage graphs (empty identifiers, conflicting
        duplicate results, dangling edges, illegal edge types or
        contradictory duplicate edges).
    :raises LookupError: :class:`UnknownCorrelationReferenceError` when a
        check result references a dataset or field not declared in the
        lineage graph.
    """
    declared_datasets, declared_fields, edges = _validate_lineage(lineage)
    records = _validate_results(results)
    _check_references(records, declared_datasets, declared_fields)

    upstream_of, downstream_of = _direct_lineage_neighbours(edges)

    violated_by_sample: Dict[str, List[Dict[str, Any]]] = {}
    for record in records:
        if record["violated"]:
            violated_by_sample.setdefault(record["sample_id"], []).append(record)

    events: List[Dict[str, Any]] = []
    for sample_id, sample_records in violated_by_sample.items():
        violated_fields = {
            (record["dataset_id"], record["field_id"])
            for record in sample_records
        }

        for component in _lineage_field_components(violated_fields, edges):
            rules = sorted(
                record["rule_id"]
                for record in sample_records
                if (record["dataset_id"], record["field_id"]) in component
            )
            upstream_fields: Set[FieldId] = set()
            downstream_fields: Set[FieldId] = set()
            for field in component:
                upstream_fields |= upstream_of.get(field, set())
                downstream_fields |= downstream_of.get(field, set())
            upstream_fields -= component
            downstream_fields -= component

            events.append(
                {
                    "sample_id": sample_id,
                    "rules": rules,
                    "fields": [_field_ref(field) for field in sorted(component)],
                    "upstream_fields": [
                        _field_ref(field) for field in sorted(upstream_fields)
                    ],
                    "downstream_fields": [
                        _field_ref(field) for field in sorted(downstream_fields)
                    ],
                }
            )

    events.sort(
        key=lambda event: (
            event["sample_id"],
            [(field["dataset"], field["field"]) for field in event["fields"]],
        )
    )
    return {"events": events}


def correlate_linked_violations(
    results: Any, lineage: Any, sample_links: Any
) -> Dict[str, Any]:
    """Group violation results across linked samples into correlation events.

    This is the cross-dataset counterpart of :func:`correlate_violations`:
    ``results`` and ``lineage`` use exactly the same shape and validation,
    while ``sample_links`` declares undirected relationships between the
    samples appearing in ``results``.

    :param results: see :func:`correlate_violations`.
    :param lineage: see :func:`correlate_violations`.
    :param sample_links: list of link objects, each with exactly the keys
        ``left`` and ``right``; each endpoint is an object with exactly
        the keys ``dataset_id`` and ``sample_id`` (non-empty strings).
        Links are undirected, so a link and its left/right reversal are
        the same relationship. Endpoints never carry values and values
        are never compared: matching is by ``dataset_id`` and
        ``sample_id`` only, and every endpoint must match a result.
    :returns: ``{"events": [...]}`` where each event has exactly the keys
        ``sample_refs``, ``rules``, ``fields``, ``upstream_fields`` and
        ``downstream_fields``. Sample references are built from the
        violated results' ``dataset_id``/``sample_id`` and grouped by the
        undirected transitive closure of ``sample_links``; within one
        sample component the violated fields are split into events by the
        same lineage-adjacency semantics as :func:`correlate_violations`.
        ``sample_refs`` are deduplicated and sorted by ``(dataset_id,
        sample_id)``, ``rules`` are deduplicated rule ids sorted
        ascending, ``fields`` are deduplicated ``{"dataset", "field"}``
        references sorted by ``(dataset, field)``, and the upstream /
        downstream sets hold the direct lineage neighbours of the
        affected fields outside the event. Sample components with no
        violated result produce no events, so an all-passing batch yields
        ``{"events": []}``.
    :raises ValueError: :class:`InvalidCorrelationInputError` on malformed
        results or lineage, and
        :class:`InvalidLinkedCorrelationInputError` on malformed
        ``sample_links`` (not a list, missing/extra keys, empty
        identifiers, self links or duplicate relationships).
    :raises LookupError: :class:`UnknownCorrelationReferenceError` when a
        result references an undeclared dataset or field, and
        :class:`UnknownLinkedCorrelationReferenceError` when a sample-link
        endpoint has no matching result.
    """
    declared_datasets, declared_fields, edges = _validate_lineage(lineage)
    records = _validate_results(results)
    _check_references(records, declared_datasets, declared_fields)
    links = _validate_sample_links(sample_links, records)

    upstream_of, downstream_of = _direct_lineage_neighbours(edges)

    violated_records = [record for record in records if record["violated"]]

    events: List[Dict[str, Any]] = []
    for sample_component in _sample_components(records, links):
        group_records = [
            record
            for record in violated_records
            if (record["dataset_id"], record["sample_id"]) in sample_component
        ]
        # A component whose results all pass produces no event.
        if not group_records:
            continue

        violated_fields = {
            (record["dataset_id"], record["field_id"])
            for record in group_records
        }

        for field_component in _lineage_field_components(
            violated_fields, edges
        ):
            component_records = [
                record
                for record in group_records
                if (record["dataset_id"], record["field_id"])
                in field_component
            ]
            refs = {
                (record["dataset_id"], record["sample_id"])
                for record in component_records
            }
            rules = sorted({record["rule_id"] for record in component_records})

            upstream_fields: Set[FieldId] = set()
            downstream_fields: Set[FieldId] = set()
            for field in field_component:
                upstream_fields |= upstream_of.get(field, set())
                downstream_fields |= downstream_of.get(field, set())
            upstream_fields -= field_component
            downstream_fields -= field_component

            events.append(
                {
                    "sample_refs": [
                        _sample_ref(ref) for ref in sorted(refs)
                    ],
                    "rules": rules,
                    "fields": [
                        _field_ref(field)
                        for field in sorted(field_component)
                    ],
                    "upstream_fields": [
                        _field_ref(field) for field in sorted(upstream_fields)
                    ],
                    "downstream_fields": [
                        _field_ref(field) for field in sorted(downstream_fields)
                    ],
                }
            )

    events.sort(
        key=lambda event: (
            [
                (ref["dataset_id"], ref["sample_id"])
                for ref in event["sample_refs"]
            ],
            [
                (field["dataset"], field["field"])
                for field in event["fields"]
            ],
        )
    )
    return {"events": events}

"""Upstream/downstream lineage tracing over declared table/column fields.

The public entry point is :func:`trace_field_lineage`. ``fields`` declares
the known columns per table; edges point from a ``source`` field to a
``target`` field: upstream traversal follows edges backwards, downstream
traversal follows them forwards.

Graph structure problems raise :class:`InvalidFieldLineageInputError`, bad
query arguments raise :class:`InvalidFieldLineageQueryError` and a target
that is not declared in ``fields`` raises
:class:`UnknownFieldLineageTargetError`; all three subclass
:class:`ValueError`.
"""

from __future__ import annotations

from collections import deque
from typing import Any, Dict, List, Optional, Set, Tuple

__all__ = [
    "trace_field_lineage",
    "InvalidFieldLineageInputError",
    "InvalidFieldLineageQueryError",
    "UnknownFieldLineageTargetError",
]

VALID_DIRECTIONS = ("upstream", "downstream", "both")
_EDGE_KEYS = frozenset({"source", "target"})
_FIELD_KEYS = frozenset({"table", "column"})

# A field is identified by its (table, column) pair.
FieldId = Tuple[str, str]


class InvalidFieldLineageInputError(ValueError):
    """The field lineage graph (``fields``/``edges``) is missing or malformed."""


class InvalidFieldLineageQueryError(ValueError):
    """The query arguments (``target``/``direction``/``max_depth``) are bad."""


class UnknownFieldLineageTargetError(ValueError):
    """The queried ``target`` is not declared among ``fields``."""


def _field_id(endpoint: Dict[str, Any]) -> FieldId:
    return (endpoint["table"], endpoint["column"])


def _validate_fields(fields: Any) -> Set[FieldId]:
    if not isinstance(fields, dict):
        raise InvalidFieldLineageInputError(
            "fields must be an object mapping table ids to field id lists"
        )

    declared: Set[FieldId] = set()
    for table, columns in fields.items():
        if not isinstance(table, str) or not table:
            raise InvalidFieldLineageInputError(
                f"fields key must be a non-empty table id string: {table!r}"
            )
        if not isinstance(columns, list):
            raise InvalidFieldLineageInputError(
                f"fields[{table!r}] must be a list of field ids"
            )
        seen_columns: Set[str] = set()
        for index, column in enumerate(columns):
            if not isinstance(column, str) or not column:
                raise InvalidFieldLineageInputError(
                    f"fields[{table!r}][{index}] must be a non-empty "
                    "field id string"
                )
            if column in seen_columns:
                raise InvalidFieldLineageInputError(
                    f"duplicate field id in table {table!r}: {column!r}"
                )
            seen_columns.add(column)
            declared.add((table, column))
    return declared


def _check_endpoint(endpoint: Any, declared: Set[FieldId], where: str) -> None:
    if not isinstance(endpoint, dict):
        raise InvalidFieldLineageInputError(f"{where} must be an object")
    keys = set(endpoint)
    if keys != _FIELD_KEYS:
        missing = sorted(_FIELD_KEYS - keys)
        if missing:
            raise InvalidFieldLineageInputError(
                f"{where} is missing keys: {missing}"
            )
        unknown = sorted(keys - _FIELD_KEYS)
        raise InvalidFieldLineageInputError(
            f"{where} has unsupported keys: {unknown}"
        )
    table = endpoint["table"]
    column = endpoint["column"]
    if not isinstance(table, str) or not table:
        raise InvalidFieldLineageInputError(
            f"{where}.table must be a non-empty string"
        )
    if not isinstance(column, str) or not column:
        raise InvalidFieldLineageInputError(
            f"{where}.column must be a non-empty string"
        )
    if (table, column) not in declared:
        raise InvalidFieldLineageInputError(
            f"{where} is not a declared field: {endpoint!r}"
        )


def _validate_edges(edges: Any, declared: Set[FieldId]) -> None:
    if not isinstance(edges, list):
        raise InvalidFieldLineageInputError("edges must be a list")

    seen_edges: Set[Tuple[FieldId, FieldId]] = set()
    for index, edge in enumerate(edges):
        if not isinstance(edge, dict):
            raise InvalidFieldLineageInputError(
                f"edges[{index}] must be an object"
            )
        keys = set(edge)
        if keys != _EDGE_KEYS:
            missing = sorted(_EDGE_KEYS - keys)
            if missing:
                raise InvalidFieldLineageInputError(
                    f"edges[{index}] is missing keys: {missing}"
                )
            unknown = sorted(keys - _EDGE_KEYS)
            raise InvalidFieldLineageInputError(
                f"edges[{index}] has unsupported keys: {unknown}"
            )

        _check_endpoint(edge["source"], declared, f"edges[{index}].source")
        _check_endpoint(edge["target"], declared, f"edges[{index}].target")

        pair = (_field_id(edge["source"]), _field_id(edge["target"]))
        if pair in seen_edges:
            raise InvalidFieldLineageInputError(
                f"duplicate edge: {edge['source']!r} -> {edge['target']!r}"
            )
        seen_edges.add(pair)


def _validate_query(target: Any, direction: Any, max_depth: Any) -> None:
    if not isinstance(target, dict):
        raise InvalidFieldLineageQueryError(
            "target must be an object with 'table' and 'column'"
        )
    keys = set(target)
    if keys != _FIELD_KEYS:
        missing = sorted(_FIELD_KEYS - keys)
        if missing:
            raise InvalidFieldLineageQueryError(
                f"target is missing keys: {missing}"
            )
        unknown = sorted(keys - _FIELD_KEYS)
        raise InvalidFieldLineageQueryError(
            f"target has unsupported keys: {unknown}"
        )
    if not isinstance(target["table"], str) or not target["table"]:
        raise InvalidFieldLineageQueryError(
            "target.table must be a non-empty string"
        )
    if not isinstance(target["column"], str) or not target["column"]:
        raise InvalidFieldLineageQueryError(
            "target.column must be a non-empty string"
        )
    if direction not in VALID_DIRECTIONS:
        raise InvalidFieldLineageQueryError(
            f"direction must be one of {list(VALID_DIRECTIONS)}, "
            f"got {direction!r}"
        )
    if max_depth is not None:
        # bool is a subclass of int, but JSON true/false are not depths.
        if isinstance(max_depth, bool) or not isinstance(max_depth, int):
            raise InvalidFieldLineageQueryError(
                "max_depth must be null or an integer >= 0"
            )
        if max_depth < 0:
            raise InvalidFieldLineageQueryError(
                f"max_depth must be >= 0, got {max_depth}"
            )


def _build_adjacency(
    edges: List[Dict[str, Any]]
) -> Tuple[Dict[FieldId, List[FieldId]], Dict[FieldId, List[FieldId]]]:
    outgoing: Dict[FieldId, List[FieldId]] = {}
    incoming: Dict[FieldId, List[FieldId]] = {}
    for edge in edges:
        source = _field_id(edge["source"])
        target = _field_id(edge["target"])
        outgoing.setdefault(source, []).append(target)
        incoming.setdefault(target, []).append(source)
    return outgoing, incoming


def _walk(
    start: FieldId,
    neighbors: Dict[FieldId, List[FieldId]],
    max_depth: Optional[int],
) -> Dict[FieldId, int]:
    """BFS from ``start``; first visit wins, so depths are shortest."""
    depths = {start: 0}
    if max_depth == 0:
        return depths

    queue = deque([(start, 0)])
    while queue:
        field, depth = queue.popleft()
        if max_depth is not None and depth >= max_depth:
            continue
        next_depth = depth + 1
        for nxt in neighbors.get(field, ()):
            if nxt not in depths:
                depths[nxt] = next_depth
                queue.append((nxt, next_depth))
    return depths


def _side(
    depths: Optional[Dict[FieldId, int]],
    edges: List[Dict[str, Any]],
) -> Dict[str, Any]:
    if depths is None:
        return {"fields": [], "edges": []}

    fields = [
        {"table": table, "column": column, "depth": depth}
        for (table, column), depth in sorted(
            depths.items(), key=lambda item: (item[1], item[0][0], item[0][1])
        )
    ]
    side_edges = [
        edge
        for edge in edges
        if _field_id(edge["source"]) in depths
        and _field_id(edge["target"]) in depths
    ]
    side_edges.sort(
        key=lambda edge: (
            edge["source"]["table"],
            edge["source"]["column"],
            edge["target"]["table"],
            edge["target"]["column"],
        )
    )
    return {"fields": fields, "edges": side_edges}


def trace_field_lineage(
    fields: Any,
    edges: Any,
    target: Any,
    direction: Any = "both",
    max_depth: Any = None,
) -> Dict[str, Any]:
    """Trace upstream/downstream field-level lineage of ``target``.

    :param fields: object mapping non-empty table id strings to lists of
        distinct non-empty field id strings.
    :param edges: list of ``{"source": ..., "target": ...}`` objects whose
        endpoints are ``{"table": ..., "column": ...}`` objects declared in
        ``fields``; duplicate edges are rejected, self-loops and cycles are
        legal.
    :param target: ``{"table": ..., "column": ...}`` field to trace from;
        depth 0 in every returned side.
    :param direction: ``"upstream"``, ``"downstream"`` or ``"both"``
        (default ``"both"``).
    :param max_depth: ``None`` for unlimited (default) or an integer ``>= 0``;
        ``0`` returns only ``target``. Booleans are not integers here.
    :returns: ``{"target", "direction", "max_depth",
        "upstream": {"fields", "edges"}, "downstream": {"fields", "edges"}}``.
        Each populated side lists fields as ``{"table", "column", "depth"}``
        sorted by ``(depth, table, column)`` and includes every original edge
        whose endpoints are in the side, sorted by ``(source.table,
        source.column, target.table, target.column)``. The side not queried
        is returned empty.
    :raises ValueError: :class:`InvalidFieldLineageInputError`,
        :class:`InvalidFieldLineageQueryError` or
        :class:`UnknownFieldLineageTargetError`.
    """
    declared = _validate_fields(fields)
    _validate_edges(edges, declared)
    _validate_query(target, direction, max_depth)

    start = _field_id(target)
    if start not in declared:
        raise UnknownFieldLineageTargetError(
            f"target is not declared in fields: {target!r}"
        )

    outgoing, incoming = _build_adjacency(edges)

    upstream_depths: Optional[Dict[FieldId, int]] = None
    downstream_depths: Optional[Dict[FieldId, int]] = None
    if direction in ("upstream", "both"):
        upstream_depths = _walk(start, incoming, max_depth)
    if direction in ("downstream", "both"):
        downstream_depths = _walk(start, outgoing, max_depth)

    return {
        "target": target,
        "direction": direction,
        "max_depth": max_depth,
        "upstream": _side(upstream_depths, edges),
        "downstream": _side(downstream_depths, edges),
    }

"""Field-level quality impact analysis over datasets, rules and samples.

The public entry point is :func:`analyze_field_impacts`. It combines a
field-level lineage graph with rule validation results and anomalous
samples: from every seed field it collects the fields reachable along at
least one directed edge (self-loops and cycles leading back to a seed
count as reachability), then reports the non-passing rules touching those
fields together with the anomalous samples that can actually be located.

Dangling edges (an endpoint referencing a dataset or field not declared
in ``datasets``) never abort the analysis: they are skipped during
traversal and written, sorted by their four endpoint keys, to
``unresolvedReferences``.

Structural problems raise :class:`ImpactInputError`, a :class:`ValueError`;
there is no partial result and no other business error.
"""

from __future__ import annotations

from collections import deque
from typing import Any, Dict, List, Set, Tuple

__all__ = [
    "analyze_field_impacts",
    "ImpactInputError",
]

_PAYLOAD_KEYS = frozenset(
    {
        "datasets",
        "lineageEdges",
        "validationResults",
        "anomalySamples",
        "seedFields",
    }
)
_EDGE_KEYS = frozenset(
    {"sourceDataset", "sourceField", "targetDataset", "targetField"}
)
_RULE_KEYS = frozenset(
    {"ruleId", "status", "fields", "failedSampleIds"}
)
_SAMPLE_KEYS = frozenset({"dataset", "fieldValues"})
_FIELD_REF_KEYS = frozenset({"dataset", "field"})
_VALID_STATUSES = frozenset({"passed", "failed", "skipped"})

# A field is identified by its (dataset, field) pair.
FieldId = Tuple[str, str]


class ImpactInputError(ValueError):
    """The impact-analysis payload is missing or malformed."""


def _error(message: str) -> ImpactInputError:
    return ImpactInputError(message)


def _check_keys(obj: Any, expected: frozenset, where: str) -> None:
    if not isinstance(obj, dict):
        raise _error(f"{where} must be an object")
    keys = set(obj)
    if keys != expected:
        missing = sorted(expected - keys)
        if missing:
            raise _error(f"{where} is missing keys: {missing}")
        unknown = sorted(keys - expected)
        raise _error(f"{where} has unsupported keys: {unknown}")


def _check_field_ref(ref: Any, where: str) -> FieldId:
    _check_keys(ref, _FIELD_REF_KEYS, where)
    dataset = ref["dataset"]
    field = ref["field"]
    if not isinstance(dataset, str) or not dataset:
        raise _error(f"{where}.dataset must be a non-empty string")
    if not isinstance(field, str) or not field:
        raise _error(f"{where}.field must be a non-empty string")
    return (dataset, field)


def _full_name(field_id: FieldId) -> str:
    return f"{field_id[0]}.{field_id[1]}"


def _name_path(path: Tuple[FieldId, ...]) -> Tuple[str, ...]:
    """Ordering view of a reference sequence: full names ``dataset.field``."""
    return tuple(_full_name(node) for node in path)


def _validate_datasets(datasets: Any) -> Set[FieldId]:
    """Validate ``datasets`` and return the declared fields.

    Duplicate datasets (as object keys they are already distinct) and
    duplicate field names are legal, so the declarations form a set.
    """
    if not isinstance(datasets, dict):
        raise _error(
            "datasets must be an object mapping dataset ids to field lists"
        )

    declared_fields: Set[FieldId] = set()
    for dataset, fields in datasets.items():
        if not isinstance(dataset, str) or not dataset:
            raise _error(
                f"datasets key must be a non-empty dataset id string: "
                f"{dataset!r}"
            )
        if not isinstance(fields, list):
            raise _error(
                f"datasets[{dataset!r}] must be a list of field ids"
            )
        for index, field in enumerate(fields):
            if not isinstance(field, str) or not field:
                raise _error(
                    f"datasets[{dataset!r}][{index}] must be a non-empty "
                    "field id string"
                )
            declared_fields.add((dataset, field))
    return declared_fields


def _validate_edges(
    edges: Any,
    declared_fields: Set[FieldId],
) -> Tuple[
    List[Tuple[FieldId, FieldId]],
    List[Dict[str, str]],
]:
    """Validate ``lineageEdges``.

    Returns the resolvable directed edges as ``(source, target)`` pairs and
    the dangling edges (an endpoint not declared in ``datasets``) as
    four-key dictionaries. Duplicate edges in either group are legal and
    deduplicated.
    """
    if not isinstance(edges, list):
        raise _error("lineageEdges must be a list")

    resolved_set: Set[Tuple[FieldId, FieldId]] = set()
    unresolved_set: Set[Tuple[str, str, str, str]] = set()

    for index, edge in enumerate(edges):
        _check_keys(edge, _EDGE_KEYS, f"lineageEdges[{index}]")
        source_dataset = edge["sourceDataset"]
        source_field = edge["sourceField"]
        target_dataset = edge["targetDataset"]
        target_field = edge["targetField"]
        for key, value in (
            ("sourceDataset", source_dataset),
            ("sourceField", source_field),
            ("targetDataset", target_dataset),
            ("targetField", target_field),
        ):
            if not isinstance(value, str) or not value:
                raise _error(
                    f"lineageEdges[{index}].{key} must be a non-empty string"
                )

        source = (source_dataset, source_field)
        target = (target_dataset, target_field)
        if source in declared_fields and target in declared_fields:
            resolved_set.add((source, target))
        else:
            unresolved_set.add(
                (source_dataset, source_field, target_dataset, target_field)
            )

    resolved = sorted(resolved_set, key=lambda pair: (_full_name(pair[0]), _full_name(pair[1])))
    unresolved = [
        {
            "sourceDataset": sd,
            "sourceField": sf,
            "targetDataset": td,
            "targetField": tf,
        }
        for sd, sf, td, tf in sorted(unresolved_set)
    ]
    return resolved, unresolved


def _validate_rules(rules: Any) -> List[Dict[str, Any]]:
    """Validate ``validationResults``.

    Rule field references must be structurally valid ``{dataset, field}``
    objects with non-empty identifiers; a reference to a field not declared
    in ``datasets`` is tolerated (it can never intersect a downstream set).
    """
    if not isinstance(rules, list):
        raise _error("validationResults must be a list")

    validated: List[Dict[str, Any]] = []
    for index, rule in enumerate(rules):
        _check_keys(rule, _RULE_KEYS, f"validationResults[{index}]")

        rule_id = rule["ruleId"]
        if not isinstance(rule_id, str) or not rule_id:
            raise _error(
                f"validationResults[{index}].ruleId must be a non-empty string"
            )

        status = rule["status"]
        if not isinstance(status, str) or status not in _VALID_STATUSES:
            raise _error(
                f"validationResults[{index}].status must be one of "
                f"{sorted(_VALID_STATUSES)}, got {status!r}"
            )

        raw_fields = rule["fields"]
        if not isinstance(raw_fields, list):
            raise _error(
                f"validationResults[{index}].fields must be a list"
            )
        fields: Set[FieldId] = set()
        for field_index, ref in enumerate(raw_fields):
            fields.add(
                _check_field_ref(
                    ref,
                    f"validationResults[{index}].fields[{field_index}]",
                )
            )

        failed_ids = rule["failedSampleIds"]
        if not isinstance(failed_ids, list):
            raise _error(
                f"validationResults[{index}].failedSampleIds must be a list"
            )
        for sample_index, sample_id in enumerate(failed_ids):
            if not isinstance(sample_id, str) or not sample_id:
                raise _error(
                    f"validationResults[{index}].failedSampleIds"
                    f"[{sample_index}] must be a non-empty string"
                )

        validated.append(
            {
                "ruleId": rule_id,
                "status": status,
                "fields": fields,
                "failedSampleIds": failed_ids,
            }
        )
    return validated


def _validate_samples(samples: Any) -> Set[str]:
    """Validate ``anomalySamples``; return the located sample ids.

    A sample id is locatable simply by being a key in ``anomalySamples``.
    """
    if not isinstance(samples, dict):
        raise _error(
            "anomalySamples must be an object mapping sample ids to samples"
        )

    for sample_id, sample in samples.items():
        if not isinstance(sample_id, str) or not sample_id:
            raise _error(
                f"anomalySamples key must be a non-empty sample id string: "
                f"{sample_id!r}"
            )
        _check_keys(sample, _SAMPLE_KEYS, f"anomalySamples[{sample_id!r}]")

        dataset = sample["dataset"]
        if not isinstance(dataset, str) or not dataset:
            raise _error(
                f"anomalySamples[{sample_id!r}].dataset must be a "
                "non-empty string"
            )

        field_values = sample["fieldValues"]
        if not isinstance(field_values, dict):
            raise _error(
                f"anomalySamples[{sample_id!r}].fieldValues must be an object"
            )
        for field_name in field_values:
            if not isinstance(field_name, str) or not field_name:
                raise _error(
                    f"anomalySamples[{sample_id!r}].fieldValues key must be "
                    f"a non-empty field id string: {field_name!r}"
                )
            # Values are any JSON value, including null; nothing to check.
    return set(samples)


def _validate_seeds(seeds: Any) -> List[FieldId]:
    """Validate ``seedFields`` and keep the original order (duplicates kept)."""
    if not isinstance(seeds, list):
        raise _error("seedFields must be a list")

    ordered: List[FieldId] = []
    for index, ref in enumerate(seeds):
        ordered.append(_check_field_ref(ref, f"seedFields[{index}]"))
    return ordered


def _shortest_paths(
    start: FieldId,
    outgoing: Dict[FieldId, List[FieldId]],
) -> Dict[FieldId, Tuple[FieldId, ...]]:
    """Shortest reference sequence from ``start`` to every field reachable
    along one or more edges.

    A plain BFS fixes the shortest distance of every field; the
    lexicographically smallest sequence of that length is then a dynamic
    program by increasing distance -- each field prepends the smallest
    sequence of a predecessor one edge closer. A self-loop or a longer
    cycle leading back to the seed also makes the seed reachable: its
    sequence is the smallest ``path(u) + (seed,)`` over every edge
    ``u -> seed``.
    """
    dist: Dict[FieldId, int] = {start: 0}
    queue = deque([start])
    while queue:
        current = queue.popleft()
        for nxt in outgoing.get(current, ()):
            if nxt not in dist:
                dist[nxt] = dist[current] + 1
                queue.append(nxt)

    # Incoming adjacency lets every field scan its predecessors.
    incoming: Dict[FieldId, List[FieldId]] = {}
    for source, targets in outgoing.items():
        for target in targets:
            incoming.setdefault(target, []).append(source)

    best: Dict[FieldId, Tuple[FieldId, ...]] = {start: (start,)}
    for depth in range(1, max(dist.values(), default=0) + 1):
        for field_id in (node for node, d in dist.items() if d == depth):
            candidates = [
                best[predecessor] + (field_id,)
                for predecessor in incoming.get(field_id, ())
                if dist.get(predecessor) == depth - 1
            ]
            best[field_id] = min(candidates, key=_name_path)

    paths = {node: best[node] for node in dist if node != start}

    # Any edge u -> start closes a cycle; the shortest one wins, then the
    # lexicographically smallest reference sequence.
    cycles = [
        best[node] + (start,)
        for node in incoming.get(start, ())
        if node != start
    ]
    self_loop = start in outgoing.get(start, ())
    if self_loop:
        cycles.append((start, start))
    if cycles:
        paths[start] = min(
            cycles, key=lambda sequence: (len(sequence), _name_path(sequence))
        )

    return paths


def analyze_field_impacts(payload: Any) -> Dict[str, Any]:
    """Analyze the downstream quality impact of a batch of seed fields.

    :param payload: object with exactly the keys ``datasets``,
        ``lineageEdges``, ``validationResults``, ``anomalySamples`` and
        ``seedFields``. ``datasets`` maps non-empty dataset ids to lists of
        non-empty field ids; ``lineageEdges`` lists ``{sourceDataset,
        sourceField, targetDataset, targetField}`` objects;
        ``validationResults`` lists ``{ruleId, status, fields,
        failedSampleIds}`` rules with ``status`` one of ``passed`` /
        ``failed`` / ``skipped`` and ``fields`` a list of ``{dataset,
        field}`` references declared in ``datasets``; ``anomalySamples``
        maps non-empty sample ids to ``{dataset, fieldValues}``;
        ``seedFields`` is a list of ``{dataset, field}`` references.
    :returns: ``{"status": "ok", "impacts": [...],
        "unresolvedReferences": [...]}``. ``impacts`` keeps the original
        ``seedFields`` order; each impact is ``{"seed", "downstreamFields",
        "affectedRules", "anomalySamples", "paths"}``. Downstream fields
        are the fields reachable along one or more resolvable directed
        edges (self-loops and edges back to the seed count), deduplicated
        and sorted by full name ``dataset.field``; rules are the
        non-``passed`` rules touching a downstream field, sorted by
        ``ruleId``; samples are the locatable ids (those present in
        ``anomalySamples``) among their ``failedSampleIds``, sorted
        ascending; ``paths`` holds one reference sequence per downstream
        field in the same ascending full-name order, each the shortest
        chain of ``{dataset, field}`` refs from the seed to that field
        (ties broken lexicographically). Dangling edges are skipped
        during traversal and listed (four keys, sorted) in
        ``unresolvedReferences``. An unknown seed has an empty impact; an
        empty ``seedFields`` yields an empty ``impacts`` while dangling
        edges are still reported.
    :raises ValueError: :class:`ImpactInputError` on any malformed payload.
    """
    _check_keys(payload, _PAYLOAD_KEYS, "payload")

    declared_fields = _validate_datasets(payload["datasets"])
    resolved_edges, unresolved = _validate_edges(
        payload["lineageEdges"], declared_fields
    )
    rules = _validate_rules(payload["validationResults"])
    locatable_samples = _validate_samples(payload["anomalySamples"])
    seeds = _validate_seeds(payload["seedFields"])

    outgoing: Dict[FieldId, List[FieldId]] = {}
    for source, target in resolved_edges:
        outgoing.setdefault(source, []).append(target)

    impacts: List[Dict[str, Any]] = []
    for seed in seeds:
        if seed not in declared_fields:
            shortest: Dict[FieldId, Tuple[FieldId, ...]] = {}
        else:
            shortest = _shortest_paths(seed, outgoing)

        downstream = set(shortest)
        downstream_names = sorted(downstream, key=_full_name)

        # Qualifying rules are non-passed rules that touch at least one
        # downstream field; affectedRules lists their ids (deduped) and
        # anomalySamples the locatable ids among their failedSampleIds.
        qualifying = [
            rule
            for rule in rules
            if rule["status"] != "passed" and rule["fields"] & downstream
        ]
        affected_rule_ids = sorted(
            {rule["ruleId"] for rule in qualifying}
        )
        anomaly_samples = sorted(
            {
                sample_id
                for rule in qualifying
                for sample_id in rule["failedSampleIds"]
                if sample_id in locatable_samples
            }
        )

        # One reference sequence per downstream field, in the same
        # ascending full-name order as ``downstreamFields``: each is the
        # shortest chain of {dataset, field} refs from the seed to that
        # field, ties broken lexicographically.
        paths = [
            [
                {"dataset": node[0], "field": node[1]}
                for node in shortest[field_id]
            ]
            for field_id in downstream_names
        ]

        impacts.append(
            {
                "seed": {"dataset": seed[0], "field": seed[1]},
                "downstreamFields": [
                    {"dataset": field_id[0], "field": field_id[1]}
                    for field_id in downstream_names
                ],
                "affectedRules": affected_rule_ids,
                "anomalySamples": anomaly_samples,
                "paths": paths,
            }
        )

    return {
        "status": "ok",
        "impacts": impacts,
        "unresolvedReferences": unresolved,
    }

